import { Session } from './src/session.js';
const tick=()=>Promise.resolve();

let calls=0;
let s=new Session({queryFn:({signal})=>{calls++; assert(signal instanceof AbortSignal); return 'stop';},timers:{schedule:cb=>setTimeout(cb,0)}},{online:false});
let h=s.subscribe('fresh',{networkMode:'online'});
assert.deepEqual(s.snapshot('fresh'),{status:'pending',fetchStatus:'paused',data:null});
s.unsubscribe(h);
assert.deepEqual(s.snapshot('fresh'),{status:'pending',fetchStatus:'idle',data:null});
s.online(true); await tick();
assert.equal(calls,0);
h=s.subscribe('fresh',{networkMode:'online'});
assert.equal(calls,1);
await tick(); assert.equal(s.snapshot('fresh').data,'stop');

let resolve;
calls=0;
s=new Session({queryFn:()=>{calls++; return new Promise(r=>resolve=r);},timers:{schedule:cb=>setTimeout(cb,0)}});
h=s.subscribe('running');
